@startuml

class Person {
  + LastName : string
  + FirstName : string
  + Address : string
  + PhoneNumber : string
}

abstract class PersonRole {
  + IdNumber : string
}

class Patient extends PersonRole {
  + HealthNumber : string
  + DateOfBirth : date
}

class Doctor extends PersonRole {
  + PractitionerNumber : string
  + Signature : string
}

class Requisition {
  + ValidFrom : date
  + RepetitionCount : int
  + RepetitionInterval : string
}

class Test {
  + Name : string
  + Duration : string
}

class TestGroup {
  + Name : string
}

class TestResult {
  + Result : boolean
  + Report : string
}

class Appointment {
  + ConfirmationNumber : string
  + StartTime : time
  + EndTime : time
}

class Lab {
  + Name : string
  + RegistrationNumber : string
  + Address : string
  + BusinessHours : string
  + CancellationFee : float
}

Person "1" -- "0..2" PersonRole
Patient "1" -- "*" Requisition
Doctor "1" -- "*" Requisition
Requisition "1" *-- "1..*" Test
Test "*" -- "1" TestGroup
Test "1" -- "0..*" TestResult
Test "1" -- "0..*" TestResult
Doctor "1" -- "0..*" TestResult
Patient "1" -- "0..*" TestResult
Patient "1" -- "0..*" Appointment
Requisition "1" -- "0..1" Appointment
Appointment "0..*" -- "1" Lab

@enduml

